type ListBankTransactionsRequest struct {
	state     protoimpl.MessageState `protogen:"open.v1"`
	Page      *v1.PageRequest        `protobuf:"bytes,1,opt,name=page,proto3" json:"page,omitempty"`
	Status    string                 `protobuf:"bytes,2,opt,name=status,proto3" json:"status,omitempty"`       // MATCHED | UNMATCHED | ""
	Direction string                 `protobuf:"bytes,3,opt,name=direction,proto3" json:"direction,omitempty"` // DEBIT | CREDIT | ""
	Keyword   string                 `protobuf:"bytes,4,opt,name=keyword,proto3" json:"keyword,omitempty"`     // counterparty, bank_ref or remark
	// 按归属筛。空串表示不筛。
	Ownership string `protobuf:"bytes,5,opt,name=ownership,proto3" json:"ownership,omitempty"`
	// 只出「还没人认领的」（ownership 为空）。和 ownership 互斥；同时给时以
	// 这一位为准。单独一位而不是让 ownership="" 兼职，是因为空串已经是
	// 「不筛」的意思了——一个值不能同时表示「全都要」和「只要没归的」。
	OwnershipPending bool `protobuf:"varint,6,opt,name=ownership_pending,json=ownershipPending,proto3" json:"ownership_pending,omitempty"`
	// 认领状态。"" 不筛 / "OPEN" 还没认领完 / "CLAIMED" 认领完了。
	// 这就是财务每天要清的那个队列——收款对账的「待处理 / 已核销」走这里。
	ClaimStatus string `protobuf:"bytes,7,opt,name=claim_status,json=claimStatus,proto3" json:"claim_status,omitempty"`
	// 一次筛好几档归属。非空时**压过** ownership 和 ownership_pending。
	//
	// 收款对账要的「与应收无关」是「归属既不是客户、也不是待定」——那是三档
	// 的并集，单值的 ownership 表达不了。空串在这里是一个正常的元素，表示
	// 「还没人认过的那一档」。
	OwnershipIn []string `protobuf:"bytes,8,rep,name=ownership_in,json=ownershipIn,proto3" json:"ownership_in,omitempty"`
	// 看已删除的那些，而不是活着的那些。
	//
	// 这是个开关不是筛选项：两者互斥。「已删除」是和现有列表**并列**的入口，
	// 点进去只看删掉的——不是在同一张表上多勾一个框。删掉的行混在日常列表里，
	// 只会让每天要清队列的人多筛一道。
	Deleted       bool `protobuf:"varint,9,opt,name=deleted,proto3" json:"deleted,omitempty"`
	unknownFields protoimpl.UnknownFields
	sizeCache     protoimpl.SizeCache
}

